def sort_vowels_preserving_consonants(s: str) -> str:
    # Set of vowel characters (both lower‑ and upper‑case)
    vowel_set = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}

    # Extract all vowels from the original string and sort them by ASCII value
    sorted_vowels = sorted([ch for ch in s if ch in vowel_set])

    # Iterator over the sorted vowel list
    vowel_iter = iter(sorted_vowels)

    # Build the resulting string: keep consonants, replace vowels with the next sorted one
    result_chars = []
    for ch in s:
        if ch in vowel_set:
            result_chars.append(next(vowel_iter))
        else:
            result_chars.append(ch)

    return ''.join(result_chars)
```

