def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    target = (total_subarrays + 1) // 2

    def count_at_most_K(K):
        if K == 0:
            return 0
        freq = {}
        distinct = 0
        left = 0
        cnt = 0
        for right in range(n):
            x = nums[right]
            freq[x] = freq.get(x, 0) + 1
            if freq[x] == 1:
                distinct += 1
            while distinct > K:
                y = nums[left]
                freq[y] -= 1
                if freq[y] == 0:
                    distinct -= 1
                left += 1
            cnt += right - left + 1
        return cnt

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most_K(mid) >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo
```

