def totalPower(nums, k):
    MOD = 10**9 + 7
    n = len(nums)

    # dp[s][t] = number of subsequences with sum s and size t
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for num in nums:
        # iterate backwards to avoid re‑using the current element
        for s in range(k, num - 1, -1):
            for t in range(n, 0, -1):
                dp[s][t] = (dp[s][t] + dp[s - num][t - 1]) % MOD

    # pre‑compute powers of two
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    # each subsequence T with sum k contributes 2^{n‑|T|}
    ans = 0
    for t in range(1, n + 1):
        cnt = dp[k][t]
        if cnt:
            ans = (ans + cnt * pow2[n - t]) % MOD

    return ans
```

