def buyChoco(prices, money):
    # Find the two cheapest chocolates
    min1 = float('inf')  # smallest price
    min2 = float('inf')  # second smallest price

    for price in prices:
        if price < min1:
            min2 = min1
            min1 = price
        elif price < min2:
            min2 = price

    # Calculate the minimum cost to buy two chocolates
    min_cost = min1 + min2

    # Check if we can afford the two cheapest chocolates
    if min_cost <= money:
        return money - min_cost
    else:
        return money
