def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    B = 31  # enough for numbers up to 1e9 (bits 0..30)
    cnt = [0] * B

    # count how many numbers have each bit set
    for num in nums:
        for b in range(B):
            if num & (1 << b):
                cnt[b] += 1

    ans = 0
    # i-th largest number (1-indexed) gets all bits with count >= i
    for i in range(1, k + 1):
        val = 0
        for b in range(B):
            if cnt[b] >= i:
                val += 1 << b
        ans = (ans + (val * val) % MOD) % MOD

    return ans
```

