def punishmentNumber(n: int) -> int:
    """
    Returns the punishment number of n.

    For each i in [1, n] we check whether the decimal representation of i*i
    can be split into contiguous substrings whose integer values sum to i.
    If such a split exists, i*i contributes to the total sum.

    The split test is performed by a depth‑first search with memoisation
    (pos, current_sum) → bool, because the length of i*i is at most 7
    (n ≤ 1000 → i*i ≤ 1 000 000), so the search space is tiny.
    """
    from functools import lru_cache

    def can_split(square: str, target: int) -> bool:
        """Return True if `square` can be partitioned so the parts sum to target."""
        L = len(square)

        @lru_cache(maxsize=None)
        def dfs(pos: int, cur: int) -> bool:
            # reached the end of the string: succeed only if sum matches target
            if pos == L:
                return cur == target
            # prune impossible paths
            if cur > target:
                return False

            # try every possible next substring
            for nxt in range(pos + 1, L + 1):
                val = int(square[pos:nxt])          # leading zeros are fine (int discards them)
                if cur + val > target:
                    continue                         # no need to explore larger sums
                if dfs(nxt, cur + val):
                    return True
            return False

        return dfs(0, 0)

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_split(str(sq), i):
            total += sq
    return total
```
This function can be called directly, e.g. `punishmentNumber(10)` returns `182`.

