import sys
from functools import lru_cache

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))
    tiles = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))

    total_cells = H * W

    # pre‑compute masks for all possible rectangles (caching)
    @lru_cache(maxsize=None)
    def rect_mask(r: int, c: int, h: int, w: int) -> int:
        mask = 0
        for dr in range(h):
            for dc in range(w):
                mask |= 1 << ((r + dr) * W + (c + dc))
        return mask

    # can a tile be placed somewhere (ignoring other tiles)?
    def tile_can_fit(a: int, b: int) -> bool:
        return (a <= H and b <= W) or (a <= W and b <= H)

    # backtracking for a fixed subset of tiles
    def can_tile(subset):
        # sort by decreasing area – better pruning
        subset.sort(key=lambda x: x[0] * x[1], reverse=True)
        full_mask = (1 << total_cells) - 1

        @lru_cache(maxsize=None)
        def dfs(mask: int, rem):
            if mask == 0:
                return True
            # first empty cell (lowest set bit)
            pos = (mask & -mask).bit_length() - 1
            r, c = divmod(pos, W)
            for i, (a, b) in enumerate(rem):
                # try both orientations if they differ
                orientations = [(a, b)]
                if a != b:
                    orientations.append((b, a))
                for h, w in orientations:
                    if r + h > H or c + w > W:
                        continue
                    rm = rect_mask(r, c, h, w)
                    if (mask & rm) == rm:
                        new_mask = mask ^ rm
                        new_rem = rem[:i] + rem[i+1:]   # remove used tile
                        if dfs(new_mask, new_rem):
                            return True
            return False

        return dfs(full_mask, tuple(subset))

    # try all subsets of tiles
    for mask in range(1 << N):
        area_sum = 0
        fit_ok = True
        subset = []
        for i in range(N):
            if mask & (1 << i):
                a, b = tiles[i]
                area_sum += a * b
                if not tile_can_fit(a, b):
                    fit_ok = False
                    break
                subset.append((a, b))
        if not fit_ok or area_sum != total_cells:
            continue
        if can_tile(subset):
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
    solve()

```

