def findMissingAndRepeatedNumbers(grid):
    n = len(grid)
    total_elements = n * n

    # Flatten the grid and count occurrences
    seen = {}
    for row in grid:
        for num in row:
            seen[num] = seen.get(num, 0) + 1

    # Find the repeated number (appears twice)
    a = None
    for num, count in seen.items():
        if count == 2:
            a = num
            break

    # Find the missing number (not in the grid)
    b = None
    for num in range(1, total_elements + 1):
        if num not in seen:
            b = num
            break

    return [a, b]
```

