def canTraverseAllPairs(nums):
    """
    Returns True if every pair of indices (i, j) in nums can be connected by a
    sequence of traversals where an edge exists between i and j iff
    gcd(nums[i], nums[j]) > 1. Otherwise returns False.
    """
    n = len(nums)
    if n <= 1:
        return True

    # If any element is 1, it cannot be connected to any other element.
    if any(v == 1 for v in nums):
        return False

    max_val = max(nums)

    # ---------- sieve for smallest prime factor ----------
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:                     # i is prime
            step = i
            start = i * i
            for j in range(start, max_val + 1, step):
                if spf[j] == j:
                    spf[j] = i

    # ---------- Disjoint Set Union ----------
    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path compression (halving)
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    # ---------- map each prime factor to the first index that contains it ----------
    prime_to_index = {}

    for idx, val in enumerate(nums):
        x = val
        prev_factor = None
        # extract unique prime factors using spf
        while x > 1:
            p = spf[x]
            # skip duplicates of the same prime in this number
            if p != prev_factor:
                if p not in prime_to_index:
                    prime_to_index[p] = idx
                else:
                    union(idx, prime_to_index[p])
                prev_factor = p
            # divide out all occurrences of p
            while x % p == 0:
                x //= p

    # ---------- check if all indices belong to the same component ----------
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
```

