        tiles.append((a, b))

    # Total area must match
    grid_area = h * w

    # Try all subsets of tiles and all permutations
    def can_place_tiles():
        # Try all possible subsets of tiles
        for mask in range(1, 1 << n):
            subset = []
            total_area = 0
            for i in range(n):
                if mask & (1 << i):
                    a, b = tiles[i]
                    subset.append((a, b))
                    total_area += a * b

            # Area must match exactly
            if total_area != grid_area:
                continue

            # Try all permutations of this subset
            for perm in permutations(subset):
                if can_fill_grid(perm, h, w):
                    return True
        return False

    def can_fill_grid(tiles, h, w):
        # Create grid representation
        grid = [[0] * w for _ in range(h)]

        def can_place(y, x, height, width):
            if y + height > h or x + width > w:
                return False
            for i in range(y, y + height):
                for j in range(x, x + width):
                    if grid[i][j] != 0:
                        return False
            return True

        def place(y, x, height, width, tile_id):
            for i in range(y, y + height):
                for j in range(x, x + width):
                    grid[i][j] = tile_id

        def remove(y, x, height, width):
            for i in range(y, y + height):
                for j in range(x, x + width):
                    grid[i][j] = 0

        def backtrack(idx):
            if idx == len(tiles):
                return True

            a, b = tiles[idx]
            # Try both orientations
            orientations = [(a, b), (b, a)]

            for height, width in orientations:
                for y in range(h):
                    for x in range(w):
                        if can_place(y, x, height, width):
                            place(y, x, height, width, idx + 1)
                            if backtrack(idx + 1):
                                return True
                            remove(y, x, height, width)
            return False

        return backtrack(0)

    if can_place_tiles():
        print("Yes")
    else:
        print("No")

