def findMissingAndRepeatedValues(grid):
    n = len(grid)
    # Create a boolean array to keep track of seen numbers.
    # The size is n * n + 1 because values are in the range [1, n^2].
    seen = [False] * (n * n + 1)
    a = -1

    # Iterate through the grid to find the repeating number 'a'
    for row in grid:
        for val in row:
            if seen[val]:
                a = val
            else:
                seen[val] = True

    # Iterate through the range 1 to n^2 to find the missing number 'b'
    b = -1
    for i in range(1, n * n + 1):
        if not seen[i]:
            b = i
            break

    return [a, b]
