from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False

    max_val = max(nums)

    # smallest prime factor sieve
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # union-find for indices
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # map each prime factor to the first index that contains it
    prime_to_index = {}

    for i, num in enumerate(nums):
        x = num
        while x > 1:
            p = spf[x]
            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i
            while x % p == 0:
                x //= p

    # check if all indices are in the same set
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
