def min_operations(s1: str, s2: str, s3: str) -> int:
    # Compute the length of the longest common prefix (LCP)
    lcp_len = 0
    min_len = min(len(s1), len(s2), len(s3))
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            lcp_len += 1
        else:
            break

    # If no common character exists, it's impossible
    if lcp_len == 0:
        return -1

    # Minimum number of deletions = total length - 3 * LCP length
    return len(s1) + len(s2) + len(s3) - 3 * lcp_len

```

